<?php
$title='Cashier Shifts & Drawers';
$esc=static function($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');};
$can=static function($p)use($actor){return User::has_permission($actor,$p);};
$shiftModals='';
$cash=static function($c){return '₱'.number_format($c/100,2);};
$hidden=static function($action,$fields=[])use($esc){echo '<input type="hidden" name="csrf_token" value="'.$esc($_SESSION['csrf_token']).'"><input type="hidden" name="request_key" value="'.bin2hex(random_bytes(16)).'"><input type="hidden" name="action" value="'.$esc($action).'">';foreach($fields as $k=>$v)echo '<input type="hidden" name="'.$esc($k).'" value="'.$esc($v).'">';};
$start=static function($id,$label)use($esc){ob_start();echo '<div class="modal fade shift-modal" id="'.$esc($id).'" tabindex="-1" aria-labelledby="'.$esc($id).'-title" aria-hidden="true"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><div class="modal-header"><h2 class="modal-title fs-5" id="'.$esc($id).'-title">'.$esc($label).'</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button></div><div class="modal-body"><form method="post" action="'.url('?route=pos/shifts').'">';};
$end=static function($label,$style='primary')use($esc,&$shiftModals){echo '<div class="shift-actions"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Cancel</button><button type="submit" class="btn btn-'.$esc($style).'">'.$esc($label).'</button></div></form></div></div></div></div>'; $shiftModals.=ob_get_clean();};
ob_start(); ?>
<link rel="stylesheet" href="<?= url('assets/css/cash-shifts.css') ?>?v=<?= filemtime(__DIR__.'/../../assets/css/cash-shifts.css') ?>">
<div class="shift-page">
<header class="shift-heading"><div><span class="shift-eyebrow">CASH CONTROL</span><h1>Cashier shifts & drawers</h1><p>Open a register, account for every cash movement and reconcile each shift.</p></div><div class="d-flex gap-2 flex-wrap"><a class="btn btn-light" href="<?= url('?route=pos') ?>">Back to POS</a><?php if ($ready && ($can('open_cash_shift') || $can('manage_cash_shifts')) && $branch): ?><button type="button" class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#shiftOpen">Open cashier shift</button><?php endif; ?></div></header>
<?php if ($error): ?><div class="alert alert-danger" role="alert"><?= $esc($error) ?></div><?php endif; ?>
<?php if (!$ready): ?><p class="alert alert-warning">Cash shift setup is pending. Apply the cash shift migration before using this module.</p><?php else: ?>
<section class="shift-card shift-controls mb-4"><form method="get" action="<?= url('index.php') ?>" class="d-flex gap-3 align-items-end flex-wrap"><input type="hidden" name="route" value="pos/shifts"><label>Branch<select class="form-select" name="branch_id"><?php if(User::has_all_branch_access($actor)): ?><option value="">All accessible branches</option><?php endif; ?><?php foreach ($branches as $b): ?><option value="<?= (int)$b['id'] ?>" <?= (int)$branch===(int)$b['id']?'selected':'' ?>><?= $esc($b['name']) ?></option><?php endforeach; ?></select></label><button type="submit" class="btn btn-primary">Show shifts</button>
</form>
<?php if ($policy): ?><div class="shift-policy mt-3"><span class="material-symbols-outlined" aria-hidden="true">shield</span><span>Shift for pickup / other payments: <strong><?= $policy['require_open']?'Required':'Optional during setup' ?></strong> · Manager review for new shifts: <strong><?= $policy['require_approval']?'Required':'Not required' ?></strong></span><?php if ($can('manage_registers')): ?><button type="button" class="btn btn-outline-primary btn-sm ms-auto" data-bs-toggle="modal" data-bs-target="#shiftPolicy">Configure</button><?php endif; ?></div><?php else: ?><p class="small text-muted mt-3 mb-0">Select a branch to open shifts and configure its registers.</p><?php endif; ?></section>
<?php $shiftActive=($_SESSION['cash_shift_tab'] ?? '')==='schedules'?'schedules':($selected?'drawer':'shifts');unset($_SESSION['cash_shift_tab']); ?>
