<?php foreach (['schedules'=>['calendar_month','Cashier schedules',true],'shifts'=>['point_of_sale','Cashier shifts',true],'drawer'=>['account_balance_wallet','Drawer & closing',true],'registers'=>['settings','Registers & policy',$can('manage_registers')],'reports'=>['monitoring','Closing reports',$can('view_shift_reports')]] as $tab=>$meta): if (!$meta[2]) continue; ?>
<button type="button" class="nav-link <?= $shiftActive===$tab?'active':'' ?>" id="shift-tab-<?= $tab ?>" data-bs-toggle="pill" data-bs-target="#shift-pane-<?= $tab ?>" role="tab" aria-controls="shift-pane-<?= $tab ?>" aria-selected="<?= $shiftActive===$tab?'true':'false' ?>"><span class="material-symbols-outlined" aria-hidden="true"><?= $meta[0] ?></span><?= $meta[1] ?></button>
<?php endforeach; ?></nav>
<div class="tab-content shift-tab-content">
<?php require __DIR__.'/../partials/cashier_schedules.php'; ?>
