<?php if ($selected): $s=$selected; $t=$s['totals']; $own=(int)$s['cashier_id']===$actor; ?>
<section class="shift-card shift-detail mb-4"><div class="d-flex justify-content-between gap-3 flex-wrap"><div><span class="shift-eyebrow">SHIFT #<?= (int)$s['id'] ?></span><h2 class="h4 mt-2"><?= $esc($s['cashier_name']) ?></h2><p class="small text-muted"><?= $esc($s['branch_name'].' · '.$s['register_name']) ?> · Opened <?= $esc($s['opened_at']) ?></p></div><span class="shift-status"><?= $esc(str_replace('_',' ',$s['status'])) ?></span></div>
<div class="shift-metrics"><?php foreach (['Opening float'=>$t['opening_cents'],'Cash sales'=>$t['cash_sales_cents'],'Electronic sales'=>$t['electronic_sales_cents'],'Expected cash'=>$s['status']==='open'?$t['expected_cents']:CashShift::cents($s['expected_cash'],true)] as $label=>$value): ?><div><small><?= $label ?></small><strong><?= $cash($value) ?></strong></div><?php endforeach; ?></div>
<p class="shift-equation">Expected cash = opening float + cash sales + cash-in − cash-out − cash refunds ± authorized corrections. Electronic payments do not add drawer cash.</p>
<div class="row g-3 mt-1"><div class="col-md-6"><h3 class="h6">Drawer movements</h3><dl class="shift-breakdown"><?php foreach (['Cash-in'=>$t['cash_in_cents'],'Cash-out'=>$t['cash_out_cents'],'Cash refunds'=>$t['cash_refunds_cents'],'Electronic refunds'=>$t['electronic_refunds_cents'],'Corrections'=>$t['correction_cents']] as $label=>$v): ?><dt><?= $label ?></dt><dd><?= $cash($v) ?></dd><?php endforeach; ?></dl></div><div class="col-md-6"><h3 class="h6">Net payments by method</h3><dl class="shift-breakdown"><?php foreach ($t['payments'] as $label=>$v): ?><dt><?= $esc($label) ?></dt><dd><?= $cash($v) ?></dd><?php endforeach; ?></dl></div></div>
<?php if ($s['status']!=='open'): ?><div class="shift-closing"><h3 class="h6">Closing reconciliation</h3><div class="shift-metrics"><div><small>Counted cash</small><strong><?= $cash(CashShift::cents($s['counted_cash'])) ?></strong></div><div><small><?= CashShift::cents($s['difference'],true)<0?'Shortage':'Overage / shortage' ?></small><strong><?= $cash(CashShift::cents($s['difference'],true)) ?></strong></div><div><small>Closed at</small><strong class="fs-6"><?= $esc($s['closed_at']) ?></strong></div></div><p class="small mb-0 mt-3">Explanation: <?= $esc($s['close_notes'] ?: 'Balanced drawer') ?></p><?php if ($s['approved_at']): ?><p class="small mt-2 mb-0">Manager approval recorded <?= $esc($s['approved_at']) ?>.</p><?php endif; ?></div><?php endif; ?>
<div class="d-flex gap-2 flex-wrap mt-4 shift-detail-actions">
<?php if ($s['status']==='open' && (($own && $can('cash_drawer_movements')) || $can('manage_cash_shifts'))): ?><button type="button" class="btn btn-outline-primary" data-bs-toggle="modal" data-bs-target="#shiftMove">Cash-in / cash-out</button><?php endif; ?>
<?php if ($s['status']==='open' && $can('manage_cash_shifts')): ?><button type="button" class="btn btn-outline-warning" data-bs-toggle="modal" data-bs-target="#shiftCorrect">Audited correction</button><?php endif; ?>
<?php if ($s['status']==='open' && (($own && $can('close_cash_shift')) || $can('manage_cash_shifts'))): ?><button type="button" class="btn btn-success" data-bs-toggle="modal" data-bs-target="#shiftClose">Count & close shift</button><?php endif; ?>
<?php if ($s['status']==='pending_review' && !$own && (int)$s['closed_by']!==$actor && ($can('approve_cash_shifts') || $can('manage_cash_shifts'))): ?><button type="button" class="btn btn-outline-primary" data-bs-toggle="modal" data-bs-target="#shiftReview">Manager review</button><?php endif; ?>
<button type="button" class="btn btn-light" data-print-shift>Print shift summary</button><form method="post" action="<?= url('?route=pos/shifts') ?>"><?php $hidden('shift_deselect'); ?><button type="submit" class="btn btn-light">Close details</button></form></div>
<h3 class="h6 mt-4">Payment & drawer ledger</h3><div class="table-responsive"><table class="table shift-table"><thead><tr><th>Date / time</th><th>Operation</th><th>Method</th><th>Amount</th><th>Cashier / reason</th></tr></thead><tbody><?php foreach ($s['entries'] as $e): ?><tr><td><?= $esc($e['created_at']) ?></td><td><?= $esc(ucwords(str_replace('_',' ',$e['kind']))) ?><?= $e['sale_id']?' · Sale #'.(int)$e['sale_id']:'' ?></td><td><?= $esc($e['payment_method']) ?></td><td><?= $cash(CashShift::cents($e['amount'],true)) ?></td><td><?= $esc($e['actor_name']) ?><small class="d-block text-muted"><?= $esc($e['reason']) ?></small></td></tr><?php endforeach; ?></tbody></table></div>
<h3 class="h6 mt-4">Audit trail</h3><?php foreach ($s['events'] as $e): $d=json_decode($e['details'],true); ?><article class="shift-event"><strong><?= $esc(ucwords(str_replace('_',' ',$e['action']))) ?></strong><span><?= $esc($e['actor_name'].' · '.$e['created_at']) ?></span><?php if ($e['action']==='recount'): ?><p class="small mb-0">Previous count <?= $esc($d['previous_count']) ?> → revised count <?= $esc($d['counted']) ?>. Previous discrepancy <?= $esc($d['previous_difference']) ?>.</p><?php endif; ?><p class="small mb-0"><?= $esc($d['notes'] ?? $d['reason'] ?? '') ?></p></article><?php endforeach; ?></section>
<?php if ($s['status']==='open'): ?>
<?php foreach (['shiftMove'=>'Cash-in / cash-out','shiftCorrect'=>'Audited drawer correction'] as $modal=>$label): if (($modal==='shiftCorrect' && !$can('manage_cash_shifts')) || ($modal==='shiftMove' && !(($own && $can('cash_drawer_movements')) || $can('manage_cash_shifts')))) continue; $start($modal,$label); $hidden('shift_move',['shift_id'=>$s['id']]); ?>
<?php if ($modal==='shiftCorrect'): ?><input type="hidden" name="kind" value="correction"><label>Correction direction<select name="direction" class="form-select"><option value="in">Add cash</option><option value="out">Remove cash</option></select></label><?php else: ?><label>Movement<select name="kind" class="form-select"><option value="cash_in">Cash-in</option><option value="cash_out">Cash-out</option></select></label><?php endif; ?>
<label class="mt-3">Amount<input type="number" name="amount" class="form-control" min="0.01" step="0.01" required></label><label class="mt-3">Reason / adjustment reference<textarea name="notes" class="form-control" maxlength="2000" required></textarea></label><p class="small text-muted mt-3">This adds an audit entry. Existing ledger records are never overwritten.</p><?php $end('Record movement'); endforeach; ?>
<?php if (($own && $can('close_cash_shift')) || $can('manage_cash_shifts')): $start('shiftClose','Count & close cashier shift'); $hidden('shift_close',['shift_id'=>$s['id']]); ?><p class="small text-muted">Count the physical cash now. Closing freezes this shift and releases the register. Any difference requires an explanation.</p><label>Actual counted cash<input type="number" name="amount" class="form-control" min="0" step="0.01" required></label><label class="mt-3">Closing notes / discrepancy explanation<textarea name="notes" class="form-control" maxlength="2000"></textarea></label><?php $end('Confirm count & close','success'); endif; ?>
<?php elseif ($s['status']==='pending_review' && !$own && (int)$s['closed_by']!==$actor && ($can('approve_cash_shifts') || $can('manage_cash_shifts'))): $start('shiftReview','Manager shift review'); $hidden('shift_review',['shift_id'=>$s['id']]); ?><label>Review action<select name="review_action" class="form-select"><?php if ($can('approve_cash_shifts')): ?><option value="approve">Approve closing summary</option><?php endif; ?><?php if ($can('manage_cash_shifts')): ?><option value="recount">Record an audited recount</option><?php endif; ?></select></label><label class="mt-3">Recounted cash (only for a recount)<input name="amount" type="number" class="form-control" min="0" step="0.01"></label><label class="mt-3">Review explanation / reference<textarea name="notes" class="form-control" required maxlength="2000"></textarea></label><p class="small text-muted mt-3">A recount preserves the previous count in the audit trail. Approval locks the closing summary.</p><?php $end('Save manager review','success'); endif; ?>
<?php endif; ?>
</div><div class="tab-pane fade <?= $shiftActive==='shifts'?'show active':'' ?>" id="shift-pane-shifts" role="tabpanel" aria-labelledby="shift-tab-shifts" tabindex="0"><section class="shift-card shift-list mb-4"><h2 class="h5">Cashier shifts</h2><p class="small text-muted">Active shifts appear first. Showing up to 200 accessible shifts.</p><div class="table-responsive"><table class="table shift-table"><thead><tr><th>Shift</th><th>Cashier / register</th><th>Branch</th><th>Status</th><th>Opened</th><th>Counted cash</th><th>Difference</th></tr></thead><tbody><?php foreach ($shifts as $row): ?><tr><td><form method="post" action="<?= url('?route=pos/shifts') ?>"><?php $hidden('shift_select',['shift_id'=>$row['id']]); ?><button type="submit" class="btn btn-outline-primary btn-sm">Shift #<?= (int)$row['id'] ?></button></form></td><td><?= $esc($row['cashier_name']) ?><small class="d-block text-muted"><?= $esc($row['register_name']) ?></small></td><td><?= $esc($row['branch_name']) ?></td><td><span class="shift-status"><?= $esc(str_replace('_',' ',$row['status'])) ?></span></td><td><?= $esc($row['opened_at']) ?></td><td><?= $row['counted_cash']!==null?$cash(CashShift::cents($row['counted_cash'])):'—' ?></td><td><?= $row['difference']!==null?$cash(CashShift::cents($row['difference'],true)):'—' ?></td></tr><?php endforeach; ?></tbody></table></div><?php if (!$shifts): ?><p class="shift-empty">No shifts recorded for this view.</p><?php endif; ?></section>
</div>
