<?php if ($can('manage_cash_shifts')): ?><label class="mt-3">Cashier<select name="cashier_id" class="form-select" required><option value="">Select cashier</option><?php foreach ($cashiers as $u): ?><option value="<?= (int)$u['id'] ?>"><?= $esc($u['name']) ?></option><?php endforeach; ?></select></label><?php else: ?><input type="hidden" name="cashier_id" value="<?= $actor ?>"><?php endif; ?>
<label class="mt-3">Opening float<input name="amount" type="number" class="form-control" min="0" step="0.01" required></label><p class="small text-muted mt-3">One active shift per cashier and per register. Opening time is recorded automatically. Count the opening float before opening.</p><?php $end('Open shift'); endif; ?>
<?php if ($can('manage_registers')): ?><div class="tab-pane fade" id="shift-pane-registers" role="tabpanel" aria-labelledby="shift-tab-registers" tabindex="0"><?php if (!$branch): ?><div class="shift-card shift-empty">Select a specific branch above to manage registers and its shift policy.</div><?php endif; ?>
<?php if ($can('manage_registers') && $branch): ?>
<section class="shift-card shift-registers"><div class="d-flex justify-content-between gap-3 align-items-center"><h2 class="h5 mb-0">Branch registers</h2><button type="button" class="btn btn-outline-primary" data-bs-toggle="modal" data-bs-target="#registerNew">Add register</button></div><div class="d-flex gap-3 flex-wrap mt-3"><?php foreach ($registers as $r): ?><button type="button" class="btn btn-light" data-bs-toggle="modal" data-bs-target="#register<?= (int)$r['id'] ?>"><?= $esc($r['name'].' · '.$r['status']) ?><?= $r['active_shift']?' · In use':'' ?></button><?php endforeach; ?></div></section>
<?php foreach (array_merge([['id'=>0,'name'=>'','status'=>'active']],$registers) as $r): $start($r['id']?'register'.$r['id']:'registerNew',$r['id']?'Edit branch register':'Add branch register'); $hidden('shift_register',['register_id'=>$r['id'],'branch_id'=>$branch]); ?><label>Register name<input name="name" class="form-control" value="<?= $esc($r['name']) ?>" required maxlength="100"></label><label class="mt-3">Status<select name="status" class="form-select"><option value="active">Active</option><option value="inactive" <?= $r['status']==='inactive'?'selected':'' ?>>Archived</option></select></label><?php $end('Save register'); endforeach; ?>
<?php $start('shiftPolicy','Branch shift policy'); $hidden('shift_policy',['branch_id'=>$branch]); ?><label>Open shift required for pickup payments<select name="require_open" class="form-select"><option value="0">Optional during setup</option><option value="1" <?= $policy['require_open']?'selected':'' ?>>Required for pickup payments</option></select></label><label class="mt-3">Manager approval for closing<select name="require_approval" class="form-select"><option value="1">Require independent manager review</option><option value="0" <?= !$policy['require_approval']?'selected':'' ?>>Close without approval</option></select></label><p class="small text-muted mt-3">The POS always requires an open, unlocked drawer. This policy controls other payment workflows. Closing approval is captured when each new shift opens; changing it does not alter existing shifts.</p><?php $end('Save branch policy'); endif; ?>
</div><?php endif; ?>
